import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static void bitAdd(long[] t, int i, long x) {
        int n = t.length - 1;
        for (; i <= n; i += i & -i) t[i] += x;
    }

    static long bitSum(long[] t, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        long[] keys = new long[(int) n];
        for (int i = 0; i < n; i++) keys[i] = (a[i] << 16) | i;
        Arrays.sort(keys);
        int[] rk = new int[(int) n];
        int m = 0;
        long prev = -1;
        for (int i = 0; i < n; i++) {
            long v = keys[i] >> 16;
            if (v != prev) {
                m++;
                prev = v;
            }
            rk[(int) (keys[i] & 65535)] = m;
        }
        long[] smaller = new long[(int) n];
        long[] t = new long[m + 1];
        for (int j = 0; j < n; j++) {
            smaller[j] = bitSum(t, rk[j] - 1);
            bitAdd(t, rk[j], 1);
        }
        t = new long[m + 1];
        long total = 0;
        for (int j = (int) n - 1; j >= 0; j--) {
            long larger = (n - 1 - j) - bitSum(t, rk[j]);
            total += smaller[j] * larger;
            bitAdd(t, rk[j], 1);
        }
        System.out.println(total);
    }
}
